const ERROR_MEANINGS: Record<ErrorCode, { meaning: string; action: string }> = {
  [ErrorCode.Config]: {
    meaning: 'The library or the service is misconfigured: a missing gateway key, a gateway that is not configured, a scheduler that is needed and absent.',
    action: 'Fix the configuration. Retrying cannot help.',
  },
  [ErrorCode.Validation]: {
    meaning: 'Your input failed validation before any gateway was called, or the gateway rejected a field.',
    action: 'Fix the request. The message names the offending fields.',
  },
  [ErrorCode.Unsupported]: {
    meaning: 'The gateway cannot do this (see its `capabilities`).',
    action: 'Check `subs.capabilities(provider)` before calling, or choose another approach.',
  },
  [ErrorCode.NotFound]: {
    meaning: 'The gateway has no such plan, subscription, charge or payment.',
    action: 'Check the id. For a debit you raised, the scheduler reads this as "never reached the gateway" only after a grace period.',
  },
  [ErrorCode.Auth]: {
    meaning: 'The gateway rejected your API credentials.',
    action: 'Check the key, the secret and test versus live mode.',
  },
  [ErrorCode.Conflict]: {
    meaning: 'The request conflicts with the current state: another operation is running, or the state does not allow it.',
    action: 'Read the current state, then decide. Some conflicts clear in a few seconds.',
  },
  [ErrorCode.RateLimited]: {
    meaning: 'The gateway rate-limited the request.',
    action: 'Wait and repeat. Reads are retried for you; writes are not.',
  },
  [ErrorCode.ProviderError]: {
    meaning: 'The gateway answered and refused, or reported a failure.',
    action: 'Read `providerCode` and `message`; the gateway\'s own value is kept verbatim.',
  },
  [ErrorCode.ProviderUnavailable]: {
    meaning: 'The gateway is down or erroring (HTTP 5xx).',
    action: 'Retry later. For a write, read the current state first.',
  },
  [ErrorCode.UnexpectedResponse]: {
    meaning: 'The gateway answered with a body this library could not validate.',
    action: 'The gateway may have changed. `raw` holds the body; report it.',
  },
  [ErrorCode.Network]: {
    meaning: 'The request could not be sent or the connection broke.',
    action: 'Retry a read. For a write that may have reached the gateway the code is `OUTCOME_UNKNOWN` instead.',
  },
  [ErrorCode.Timeout]: {
    meaning: 'The gateway did not answer in time.',
    action: 'Retry a read. For a write, see `OUTCOME_UNKNOWN`.',
  },
  [ErrorCode.OutcomeUnknown]: {
    meaning: 'A request that moves money was sent and no answer came back. It may or may not have happened.',
    action: 'Do not repeat it. Fetch the current state, then act on what you find.',
  },
  [ErrorCode.SignatureInvalid]: {
    meaning: 'A webhook or checkout result did not verify, or it belongs to another subscription than the one you expected. Nothing from it is trusted.',
    action: 'Answer 401 to a webhook. Check the secret and that you pass the raw body.',
  },
  [ErrorCode.Internal]: {
    meaning: 'A failure inside this library or its storage, not at a gateway.',
    action: 'Look at the message and `cause`. If a checkout verification fails with this, its `raw` carries the verification so the subscription id is not lost.',
  },
};

function retryableOf(code: ErrorCode): boolean {
  return new SubscriptionError(code, '').retryable;
}

function errorsPage(): string {
  const lines = header(
    'Errors',
    'src/constants.ts, src/errors.ts, src/server/constants.ts',
    'Everything the library throws is a `SubscriptionError` with a stable `code`. Branch on the code, never on the message.',
  );
  lines.push(
    ...table(
      ['Code', 'Meaning', 'What to do', 'Retryable', 'HTTP status in the service'],
      (Object.values(ErrorCode) as ErrorCode[]).map((value) => [
        code(value),
        ERROR_MEANINGS[value].meaning,
        ERROR_MEANINGS[value].action,
        retryableOf(value) ? 'yes' : 'no',
        String(ERROR_HTTP_STATUS[value]),
      ]),
    ),
    '',
    '`retryable` is true when repeating the same call later is safe and may succeed. It says nothing about money: for a write that may have reached the gateway the code is `OUTCOME_UNKNOWN`, which is not retryable.',
    '',
    '## Codes of the HTTP service',
    '',
    'The service adds three codes of its own, and shares `INTERNAL_ERROR` with the library.',
    '',
    ...table(
      ['Code', 'HTTP status'],
      (Object.values(ServerErrorCode) as ServerErrorCode[]).map((value) => [code(value), String(SERVER_ERROR_HTTP_STATUS[value])]),
    ),
    '',
    '## HTTP statuses',
    '',
    ...table(
      ['Status', 'Meaning'],
      Object.entries(HTTP_STATUS_DESCRIPTIONS).map(([status, description]) => [status, description]),
    ),
    '',
  );
  return lines.join('\n');
}

// ---------------------------------------------------------------------------
// Capabilities
// ---------------------------------------------------------------------------

/**
 * One entry per gateway that has an adapter. A gateway whose adapter is still being written (it is in `Provider` but not
 * here) gets a stub page in docs/gateways/ and no generated content. When its adapter lands, add it here: the tests
 * fail until its page carries the generated regions.
 */
const ADAPTER_FACTORIES: Partial<Record<Provider, () => SubscriptionProvider>> = {
  [Provider.Razorpay]: () => razorpay({ keyId: 'rzp_test_dummy', keySecret: 'dummy' }),
  [Provider.Cashfree]: () => cashfree({ clientId: 'dummy', clientSecret: 'dummy', environment: Environment.Test }),
  [Provider.PayU]: () => payu({ key: 'dummy', salt: 'dummy', environment: Environment.Test }),
};

/** The gateways with an adapter, in the order of `Provider`. */
export const PROVIDERS: Provider[] = (Object.values(Provider) as Provider[]).filter(
  (provider) => ADAPTER_FACTORIES[provider] !== undefined,
);

/** The gateways in `Provider` whose adapter does not exist yet. */
export const PROVIDERS_WITHOUT_ADAPTER: Provider[] = (Object.values(Provider) as Provider[]).filter(
  (provider) => ADAPTER_FACTORIES[provider] === undefined,
);

function adapterFor(provider: Provider): SubscriptionProvider {
  const factory = ADAPTER_FACTORIES[provider];
  if (!factory) throw new Error(`No adapter factory for ${provider}`);
  return factory();
}

const PROVIDER_LABEL: Record<string, string> = {
  [Provider.Razorpay]: 'Razorpay',
  [Provider.Cashfree]: 'Cashfree',
  [Provider.PayU]: 'PayU',
};

type CapabilityKey = Exclude<keyof Capabilities, 'provider'>;

function capabilityKeys(): CapabilityKey[] {
  return Object.keys(CapabilitiesSchema.shape).filter((key): key is CapabilityKey => key !== 'provider');
}

function capabilityDescription(key: CapabilityKey): string {
  return (CapabilitiesSchema.shape[key] as { description?: string }).description ?? '';
}

function formatCapability(value: unknown): string {
  if (value === true) return 'yes';
  if (value === false) return 'no';
  if (value === undefined) return 'not set';
  if (Array.isArray(value)) return value.map((item) => code(String(item))).join(', ');
  return code(String(value));
}

function adapterCapabilities(provider: Provider): Capabilities {
  return adapterFor(provider).capabilities;
}

function facadeCapabilities(provider: Provider, withScheduler: boolean): Capabilities {
  const subs = createSubscriptions({
    providers: [adapterFor(provider)],
    ...(withScheduler ? { scheduler: { store: new MemorySchedulerStore() } } : {}),
  });
  return subs.capabilities(provider);
}

function capabilityRows(shown: Capabilities): string[][] {
  return capabilityKeys().map((key) => [code(key), formatCapability(shown[key]), capabilityDescription(key)]);
}

function capabilitiesPage(): string {
  const lines = header(
    'Capability matrix',
    'src/providers/*/adapter.ts (the `capabilities` of each adapter), src/client.ts',
    'What each gateway adapter can do, read from the adapters themselves with dummy credentials. ' +
      'Check `subs.capabilities(provider)` at runtime instead of assuming: an operation a gateway cannot do throws `UNSUPPORTED`.',
  );
  const keys = capabilityKeys();
  lines.push(
    '## Adapters',
    '',
    ...table(
      ['Capability', ...PROVIDERS.map((provider) => (PROVIDER_LABEL[provider] ?? provider)), 'Meaning'],
      keys.map((key) => [
        code(key),
        ...PROVIDERS.map((provider) => formatCapability(adapterCapabilities(provider)[key])),
        capabilityDescription(key),
      ]),
    ),
    '',
    '## What `subs.capabilities()` reports',
    '',
    'The facade starts from the adapter\'s capabilities and adds what the billing scheduler provides. The rows below are only the ones that differ from the adapter table above; a gateway that is not listed reports exactly its adapter\'s values.',
    '',
  );
  for (const withScheduler of [false, true]) {
    lines.push(`### ${withScheduler ? 'With a scheduler configured' : 'Without a scheduler'}`, '');
    const differences: string[][] = [];
    for (const provider of PROVIDERS) {
      const adapter = adapterCapabilities(provider);
      const facade = facadeCapabilities(provider, withScheduler);
      for (const key of keys) {
        if (JSON.stringify(adapter[key]) !== JSON.stringify(facade[key])) {
          differences.push([(PROVIDER_LABEL[provider] ?? provider), code(key), formatCapability(adapter[key]), formatCapability(facade[key])]);
        }
      }
    }
    if (differences.length === 0) lines.push('No differences: every gateway reports its adapter\'s capabilities.', '');
    else lines.push(...table(['Gateway', 'Capability', 'Adapter', 'Facade'], differences), '');
  }
  return lines.join('\n');
}

// ---------------------------------------------------------------------------
// Environment variables
// ---------------------------------------------------------------------------

/** A valid value for every variable. Exhaustive: a new `EnvVar` is a compile error until it has a sample here. */
const ENV_SAMPLES: Record<(typeof EnvVar)[keyof typeof EnvVar], string> = {
  [EnvVar.ApiKey]: 'a-long-random-api-key-value',
  [EnvVar.Host]: '127.0.0.1',
  [EnvVar.Port]: '8787',
  [EnvVar.RazorpayKeyId]: 'rzp_test_dummy',
  [EnvVar.RazorpayKeySecret]: 'dummy-secret',
  [EnvVar.RazorpayWebhookSecret]: 'dummy-webhook-secret',
  [EnvVar.RazorpayDefaultDurationYears]: '10',
  [EnvVar.RazorpayBaseUrl]: 'https://api.razorpay.com',
  [EnvVar.CashfreeClientId]: 'dummy-id',
  [EnvVar.CashfreeClientSecret]: 'dummy-secret',
  [EnvVar.CashfreeEnvironment]: Environment.Test,
  [EnvVar.CashfreeWebhookSecret]: 'dummy-webhook-secret',
  [EnvVar.CashfreeApiVersion]: '2026-01-01',
  [EnvVar.CashfreeBaseUrl]: 'https://sandbox.cashfree.com/pg',
  [EnvVar.PayuKey]: 'dummy-key',
  [EnvVar.PayuSalt]: 'dummy-salt',
  [EnvVar.PayuEnvironment]: Environment.Test,
  [EnvVar.PayuSuccessUrl]: 'https://example.com/payu/success',
  [EnvVar.PayuFailureUrl]: 'https://example.com/payu/failure',
  [EnvVar.PayuConsentHashLayout]: 'six_pipes',
  [EnvVar.PayuAcceptUnsignedWebhooks]: 'false',
  [EnvVar.PayuPaymentUrl]: 'https://test.payu.in/_payment',
  [EnvVar.PayuApiUrl]: 'https://test.payu.in/merchant/postservice.php?form=2',
  [EnvVar.SchedulerStoreFile]: '/var/lib/india-subscriptions/scheduler.json',
  [EnvVar.SchedulerTickSeconds]: '300',
  [EnvVar.EventsWebhookUrl]: 'https://app.example.com/billing-events',
  [EnvVar.EventsWebhookSecret]: 'dummy-events-secret',
};

type EnvName = (typeof EnvVar)[keyof typeof EnvVar];
const ENV_NAMES = Object.values(EnvVar) as EnvName[];

function envGroup(name: EnvName): string {
  if (name.startsWith('RAZORPAY_')) return 'Razorpay';
  if (name.startsWith('CASHFREE_')) return 'Cashfree';
  if (name.startsWith('PAYU_')) return 'PayU';
  if (name.startsWith('SCHEDULER_')) return 'Billing scheduler';
  if (name.startsWith('EVENTS_WEBHOOK_')) return 'Events webhook';
  return 'Service';
}

const ENV_GROUPS = ['Service', 'Razorpay', 'Cashfree', 'PayU', 'Billing scheduler', 'Events webhook'];

function messageOf(action: () => unknown): string | undefined {
  try {
    action();
    return undefined;
  } catch (error) {
    return error instanceof Error ? error.message : String(error);
  }
}

/** Probes the real validation: a variable is required when leaving it out makes `parseServiceEnv` say so. */
function envRequirement(name: EnvName, group: string): string {
  const full: Record<string, string> = { ...ENV_SAMPLES };
  const gatewayOf = (variable: EnvName): string => envGroup(variable);
  const base: Record<string, string> = {};
  for (const variable of ENV_NAMES) {
    const owner = gatewayOf(variable);
    if (owner === group || owner === 'Service') base[variable] = full[variable] as string;
  }
  if (group === 'Billing scheduler' || group === 'Events webhook') {
    // Needs some gateway to be valid at all.
    for (const variable of [EnvVar.RazorpayKeyId, EnvVar.RazorpayKeySecret]) base[variable] = full[variable] as string;
  }
  const without = { ...base };
  delete without[name];
  const missing = messageOf(() => parseServiceEnv(without));
  if (name === EnvVar.ApiKey) {
    return missing?.includes(`${name}: is required`) ? 'yes, unless you pass `--allow-unauthenticated`' : 'no';
  }
  if (missing?.includes(`${name}: is required`)) return 'yes';
  if (group === 'Events webhook') {
    const only = { ...without };
    const other = name === EnvVar.EventsWebhookUrl ? EnvVar.EventsWebhookSecret : EnvVar.EventsWebhookUrl;
    for (const variable of [EnvVar.EventsWebhookUrl, EnvVar.EventsWebhookSecret]) delete only[variable];
    only[other] = full[other] as string;
    if (messageOf(() => parseServiceEnv(only))?.includes(`${name}: is required when`)) return `with ${code(other)}`;
  }
  return 'no';
}

function envDefault(name: EnvName): string {
  switch (name) {
    case EnvVar.Host:
      return code(DEFAULT_HOST);
    case EnvVar.Port:
      return code(String(DEFAULT_PORT));
    case EnvVar.SchedulerTickSeconds:
      return code(String(DEFAULT_TICK_SECONDS));
    default:
      return '';
  }
}

/** The comment lines above each assignment of `.env.example`. */
function envDescriptions(): Map<string, string> {
  const lines = readFileSync(join(ROOT, '.env.example'), 'utf8').split('\n');
  const result = new Map<string, string>();
  lines.forEach((line, index) => {
    const assignment = /^([A-Z][A-Z0-9_]*)=/.exec(line);
    if (!assignment) return;
    const comment: string[] = [];
    for (let back = index - 1; back >= 0 && (lines[back] ?? '').startsWith('#'); back -= 1) {
      const text = (lines[back] ?? '').replace(/^#\s?/, '').trim();
      // `# --- Razorpay (...) ---` is a section header, not part of the variable's comment.
      if (/^-{3}/.test(text)) break;
      comment.unshift(text);
    }
    result.set(assignment[1] as string, comment.join(' ').replace(/\s+/g, ' ').trim());
  });
  return result;
}

function environmentPage(): string {
  const descriptions = envDescriptions();
  const lines = header(
    'Environment variables and command line',
    'src/service-config.ts, src/cli.ts, .env.example',
    '`india-subscriptions serve` is configured only through environment variables. A variable that is unset or blank counts as absent. ' +
      'A gateway is enabled when its required variables are all present; setting only some of them is an error, never a silently disabled gateway. ' +
      'Error messages name the variable and the rule and never contain a value.',
  );
  for (const group of ENV_GROUPS) {
    lines.push(`## ${group}`, '');
    const names = ENV_NAMES.filter((name) => envGroup(name) === group);
    lines.push(
      ...table(
        ['Variable', 'Required', 'Default', 'Description'],
        names.map((name) => [code(name), envRequirement(name, group), envDefault(name), descriptions.get(name) ?? '']),
      ),
      '',
    );
  }
  lines.push(
    '## Limits',
    '',
    `${code(EnvVar.SchedulerTickSeconds)} accepts 1 to ${MAX_TICK_SECONDS}. ${code(EnvVar.Port)} accepts 0 to 65535 (0 picks a free port).`,
    '',
    '## Command line',
    '',
    '```text',
    USAGE.trimEnd(),
    '```',
    '',
  );
  return lines.join('\n');
}

// ---------------------------------------------------------------------------
// Regions inside hand-written gateway pages
// ---------------------------------------------------------------------------

function mapTable(map: Record<string, string>, head: [string, string]): string[] {
  return table(head, Object.entries(map).map(([from, to]) => [code(from), code(to)]));
}

function regionContent(name: string): string[] {
  const [kind, subject] = name.split(':') as [string, string | undefined];
  switch (kind) {
    case 'capabilities': {
      const provider = subject as Provider;
      return [
        ...table(['Capability', 'Value', 'Meaning'], capabilityRows(adapterCapabilities(provider))),
      ];
    }
    case 'razorpay-subscription-status':
      return mapTable(RazorpayMapper.SUBSCRIPTION_STATUS_MAP, ['Razorpay status', 'Unified status']);
    case 'razorpay-charge-status':
      return [
        ...mapTable(RazorpayMapper.INVOICE_STATUS_MAP, ['Razorpay invoice status', 'Unified charge status']),
        '',
        ...mapTable(RazorpayMapper.PAYMENT_STATUS_MAP, ['Razorpay payment status', 'Unified charge status']),
      ];
    case 'razorpay-refund-status':
      return mapTable(RazorpayMapper.REFUND_STATUS_MAP, ['Razorpay refund status', 'Unified refund status']);
    case 'razorpay-webhook-events':
      return mapTable(RazorpayMapper.WEBHOOK_EVENT_MAP, ['Razorpay event', 'Unified event']);
    case 'cashfree-subscription-status':
      return mapTable(CashfreeConstants.SUBSCRIPTION_STATUS_MAP, ['Cashfree subscription status', 'Unified status']);
    case 'cashfree-charge-status':
      return [
        ...mapTable(CashfreeConstants.PAYMENT_STATUS_MAP, ['Cashfree payment status', 'Unified charge status']),
        '',
        ...mapTable(CashfreeConstants.PAYMENT_TYPE_MAP, ['Cashfree payment type', 'Unified charge kind']),
      ];
    case 'cashfree-refund-status':
      return mapTable(CashfreeConstants.REFUND_STATUS_MAP, ['Cashfree refund status', 'Unified refund status']);
    case 'cashfree-webhook-events':
      return mapTable(CashfreeConstants.STATUS_EVENT_MAP, ['Status in `SUBSCRIPTION_STATUS_CHANGED`', 'Unified event']);
    case 'payu-subscription-status':
      return [
        ...mapTable(PayUConstants.CARD_MANDATE_STATUS, ['Card mandate status (`check_mandate_status`)', 'Unified status']),
        '',
        ...mapTable(PayUConstants.ENACH_MANDATE_STATUS, ['eNACH mandate status (`NB_mandate_status`)', 'Unified status']),
        '',
        ...mapTable(PayUConstants.UPI_MANDATE_STATUS, ['UPI mandate status (`upi_mandate_status`)', 'Unified status']),
      ];
    case 'payu-charge-status':
      return mapTable(PayUConstants.CHARGE_STATUS_BY_STATE, ['PayU transaction state', 'Unified charge status']);
    case 'payu-webhook-events':
      return [
        ...mapTable(PayUConstants.EVENT_BY_MANDATE_NOTIFICATION, ['Card mandate `notificationType`', 'Unified event']),
        '',
        ...mapTable(PayUConstants.EVENT_BY_UPI_ACTION, ['UPI mandate `action`', 'Unified event']),
      ];
    default:
      throw new Error(`Unknown generated region "${name}"`);
  }
}

/** Rewrites every generated region of a hand-written page. Returns undefined when the page has none. */
function fillRegions(source: string): string | undefined {
  const lines = source.split('\n');
  const output: string[] = [];
  let found = false;
  for (let i = 0; i < lines.length; i += 1) {
    const line = lines[i] as string;
    const begin = BEGIN.exec(line);
    if (!begin) {
      output.push(line);
      continue;
    }
    found = true;
    let close = i + 1;
    while (close < lines.length && lines[close] !== END) close += 1;
    if (close >= lines.length) throw new Error(`Region "${begin[1]}" has no ${END}`);
    output.push(line, '', ...regionContent(begin[1] as string), '', END);
    i = close;
  }
  return found ? output.join('\n') : undefined;
}

// ---------------------------------------------------------------------------
// Entry points
// ---------------------------------------------------------------------------

/** Every generated file, as `path relative to docs/` -> content. Does not touch the disk except to read sources. */
export function generateAll(): Map<string, string> {
  const { pages, models, scheduler } = buildPages();
  const files = new Map<string, string>();
  const put = (name: string, content: string): void => {
    files.set(`${GENERATED_DIR}/${name}`, `${content.trimEnd()}\n`);
  };
  put(MODELS_PAGE, modelsPage(models, pages));
  put(ENUMS_PAGE, enumsPage(models, scheduler));
  put(SCHEDULER_PAGE, schedulerPage(scheduler, pages));
  put(HTTP_PAGE, httpApiPage(pages));
  put('errors.md', errorsPage());
  put('capabilities.md', capabilitiesPage());
  put('environment.md', environmentPage());

  for (const provider of PROVIDERS) {
    const path = `gateways/${provider}.md`;
    const current = readFileSync(join(DOCS, path), 'utf8');
    const filled = fillRegions(current);
    if (filled !== undefined) files.set(path, filled.endsWith('\n') ? filled : `${filled}\n`);
  }
  return files;
}

export const GENERATED_PATHS = ['models', 'enums', 'scheduler-records', 'http-api', 'errors', 'capabilities', 'environment'].map(
  (name) => `${GENERATED_DIR}/${name}.md`,
);

function main(): void {
  const files = generateAll();
  for (const [path, content] of files) {
    const target = join(DOCS, path);
    mkdirSync(dirname(target), { recursive: true });
    writeFileSync(target, content);
  }
  console.log(`wrote ${files.size} files under docs/ (${[...files.keys()].join(', ')})`);
}

if (process.argv[1] !== undefined && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main();
}
